    imageHint: "ancient ruins of Ak-Beshim archaeological site",
    descriptionAdvanced: {
      de: "Ak-Beshim, in der Antike als Suyab bekannt, ist eine der bedeutendsten archäologischen Stätten Kirgisistans im Tschüi-Tal. Vom 6. bis zum 8. Jahrhundert diente die Stadt als Hauptstadt des Westlichen Türkischen Khaganats und war ein entscheidender Knotenpunkt an der Seidenstraße. Die Ruinen erstrecken sich über eine weite Fläche und zeugen von einer kosmopolitischen Vergangenheit, in der verschiedene Kulturen und Religionen aufeinandertrafen. Ausgrabungen haben die Überreste monumentaler Festungsmauern sowie zwei buddhistische Tempel und eine nestorianische Kirche freigelegt, was die religiöse Vielfalt der Region unterstreicht. Suyab war nicht nur ein Handelszentrum, sondern auch ein militärischer Außenposten, der zeitweise unter dem Einfluss der chinesischen Tang-Dynastie stand. Heute gehört die Stätte zum UNESCO-Weltkulturerbe und bietet Besuchern die Möglichkeit, die Fundamente einer einst blühenden Metropole zu erkunden, die als Brücke zwischen Ostasien, Indien und dem Nahen Osten fungierte.",
      hu: "Ak-Besim, az ókori Szujab romvárosa, Kirgizisztán egyik legértékesebb történelmi helyszíne a Csu-völgyben. Az 5. században alapított város a 6. és 8. század között a Nyugati Türk Kaganátus központjaként és fővárosaként virágzott, meghatározó szerepet töltve be a Selyemút kereskedelmi hálózatában. A régészeti feltárások során kiterjedt erődrendszerek, lakónegyedek és vallási épületek maradványai kerültek elő, amelyek a korszak kulturális sokszínűségét tükrözik. Különösen jelentősek a feltárt buddhista templomok és egy nesztoriánus keresztény templom romjai, amelyek bizonyítják, hogy Szujab a vallások találkozóhelye volt. A város egy ideig a kínai Tang-dinasztia befolyása alatt is állt, mint fontos katonai és közigazgatási végvár. Az UNESCO Világörökség részét képező területen a látogatók ma is megtekinthetik az ősi vályogfalak alapjait, amelyek egykor Közép-Ázsia egyik legfontosabb politikai és gazdasági centrumát védelmezték.",
      ro: "Ak-Beșim, cunoscut în antichitate sub numele de Suyab, reprezintă unul dintre cele mai importante situri arheologice din Kârgâzstan, situat în valea Chuy. Orașul a servit drept capitală a Kaganatului Turcic Occidental între secolele VI și VIII, fiind un punct strategic esențial pe Drumul Mătăsii. Ruinele acoperă o suprafață vastă și păstrează mărturiile unei societăți multiculturale vibrante. Arheologii au scos la lumină resturi impresionante de ziduri de fortificație, precum și fundațiile a două temple budiste și ale unei biserici nestoriene, reflectând diversitatea religioasă a epocii. Suyab a fost, de asemenea, un centru administrativ sub influența dinastiei chineze Tang, fiind locul de naștere al celebrului poet Li Bai. Astăzi, situl este inclus în Patrimoniul Mondial UNESCO, oferind o fereastră rară către perioada de aur a comerțului transcontinental, unde negustorii sogdieni, călugării budiști și războinicii nomazi își intersectau drumurile în inima Asiei Centrale.",
      en: "Ak-Beshim, historically known as Suyab, is a premier archaeological site in Kyrgyzstan's Chuy Valley, offering profound insights into the early medieval history of Central Asia. Founded in the 5th century, it rose to prominence as the capital of the Western Turkic Khaganate and functioned as a vital hub on the Silk Road trade routes. The extensive ruins reveal a complex urban layout protected by massive fortress walls. Excavations have yielded remarkable finds, including the foundations of two major Buddhist temples and a Nestorian Christian church, illustrating the town's role as a melting pot of global religions and cultures. For a period, Suyab was also a significant garrison town for the Chinese Tang Dynasty, marking the westernmost reach of their empire. Now a UNESCO World Heritage site, Ak-Beshim invites visitors to walk among the remnants of a lost metropolis that once connected the wealth of the East with the markets of the West, serving as a pillar of political and economic power for centuries.",
      es: "Ak-Beshim, también conocida como Suyab, es un antiguo asentamiento en el valle de Chuy, en Kirguistán. Fue un importante centro comercial en la Ruta de la Seda y capital del Kanato Túrquico Occidental. El asentamiento floreció entre los siglos V y X. Las excavaciones arqueológicas han sacado a la luz restos de murallas, templos, palacios y casas residenciales. Ak-Beshim ha sido propuesto como Patrimonio de la Humanidad por la UNESCO. El sitio ofrece una visión de la historia de Asia Central y del intercambio cultural a lo largo de la Ruta de la Seda.",
      pt: "Ak-Beshim, também conhecida como Suyab, é um antigo povoado no Vale de Chuy, no Quirguistão. Foi um importante centro comercial na Rota da Seda e capital do Canato Turco Ocidental. O povoado floresceu do século V ao X. Escavações arqueológicas revelaram vestígios de muralhas, templos, palácios e habitações. Ak-Beshim é proposto como Património Mundial da UNESCO. O local oferece uma visão da história da Ásia Central e do intercâmbio cultural ao longo da Rota da Seda.",
      fr: "Ak-Beshim, également connue sous le nom de Suyab, est une ancienne colonie de la vallée de Tchouï au Kirghizistan. C'était un centre commercial important sur la Route de la Soie et la capitale du Khaganat turc occidental. La colonie a prospéré du Ve au Xe siècle. Des fouilles archéologiques ont mis au jour des restes de murs d'enceinte, de temples, de palais et de maisons d'habitation. Ak-Beshim est proposé au patrimoine mondial de l'UNESCO. Le site offre un aperçu de l'histoire de l'Asie centrale et des échanges culturels le long de la Route de la Soie.",
    },
