      en: ["Built in the 11th century (circa 1040 CE).", "The dome has a diameter of 8 meters.", "The mausoleum stands 12 meters tall.", "Walls are made of fired bricks measuring 22×22×4 cm.", "Located in Gulistan village, 80 km northwest of Jalal-Abad.", "Inscriptions bear the name of the builder: 'Shah Fazil'."],
      es: ["Construido en el siglo XI (hacia 1040 d.C.).", "La cúpula tiene un diámetro de 8 metros.", "El mausoleo tiene 12 metros de altura.", "Las paredes son de ladrillos cocidos (22 × 22 × 4 cm).", "Se encuentra en Gulistan, a 80 km al noroeste de Jalal-Abad.", "Las inscripciones contienen el nombre del constructor: 'Shah Fazil'."],
