      fr: ["Construit au XIe siècle (vers 1040 après J.-C.).", "Le dôme a un diamètre de 8 mètres.", "Le mausolée mesure 12 mètres de haut.", "Les murs sont faits de briques cuites (22 × 22 × 4 cm).", "Il est situé à Gulistan, à 80 km au nord-ouest de Djalal-Abad.", "Les inscriptions mentionnent le nom du bâtisseur : 'Shah Fazil'."],
