      hu: ["A citadella a 9–10. századból származik.", "Egy 20 méter magas dombon fekszik.", "A falak helyenként 4 méter magasak.", "Az erőd területe 0,5 hektár.", "Több mint 200 érmét találtak.", "A kerámialeletek a 10. századból valók."],
      ro: ["Cetatea datează din secolele IX-X.", "Se află pe o colină de 20 de metri înălțime.", "Zidurile se păstrează până la 4 metri înălțime.", "Fortăreața ocupă o suprafață de 0,5 hectare.", "Peste 200 de monede au fost descoperite.", "Ceramica găsită datează din secolul al X-lea."],
      en: ["The citadel dates from the 9th-10th centuries CE.", "It stands on a hill 20 meters high.", "Walls are preserved up to 4 meters in height.", "The fortress covers 0.5 hectares.", "Over 200 coins have been discovered.", "Pottery finds date to the 10th century."],
      es: ["La ciudadela data de los siglos IX-X.", "Se encuentra en una colina de 20 metros de altura.", "Los muros se conservan hasta los 4 metros.", "La fortaleza cubre un área de 0,5 hectáreas.", "Se han encontrado más de 200 monedas hasta ahora.", "Los hallazgos de cerámica datan del siglo X."],
      pt: ["A cidadela data dos séculos IX-X.", "Situa-se numa colina de 20 metros de altura.", "As muralhas conservam-se até 4 metros de altura.", "A fortaleza cobre uma área de 0,5 hectares.", "Foram encontradas mais de 200 moedas até à data.", "Os achados de cerâmica datam do século X."],
