      pt: "Vestígios arqueológicos de uma cidade medieval junto ao rio At-Bashy. O local foi um importante ponto de paragem para caravanas a caminho de Kashgar.",
      fr: "Vestiges archéologiques d'une ville médiévale au bord de la rivière At-Bashy. Le site était une étape importante pour les caravanes en route vers Kachgar.",
