      es: ["El pueblo fue fundado en 2005.", "Está a 1620 metros sobre el nivel del mar.", "Hay 15 yurtas tradicionales para visitantes.", "El museo alberga 200 piezas.", "5000 turistas visitan el pueblo anualmente.", "El taller de fieltro produce 500 m² al año."],
      pt: ["A aldeia foi fundada em 2005.", "Situa-se a 1620 metros acima do nível do mar.", "Existem 15 yurtas tradicionais para visitantes.", "O museu alberga 200 peças.", "5000 turistas visitam a aldeia anualmente.", "A oficina de feltro produz 500 m² por ano."],
      fr: ["Le village a été fondé en 2005.", "Il est situé à 1620 mètres d'altitude.", "Il y a 15 yourtes traditionnelles pour les visiteurs.", "Le musée abrite 200 objets.", "5000 touristes visitent le village chaque année.", "L'atelier de feutre produit 500 mètres carrés de feutre par an."],
