      pt: ["O cemitério data dos séculos I-V d.C.", "Existem mais de 100 túmulos.", "Os círculos de pedra têm um diâmetro de 2 a 4 metros.", "O local foi descoberto em 1965.", "As oferendas funerárias incluem 200 vasos cerâmicos.", "O cemitério fica a 3 km a oeste de Ken-Kol."],
      fr: ["Le cimetière date du Ier au Ve siècle de notre ère.", "Il y a plus de 100 tombes.", "Les cercles de pierres ont un diamètre de 2 à 4 mètres.", "Le site a été découvert en 1965.", "Les objets funéraires comprennent 200 récipients en céramique.", "Le cimetière est situé à 3 km à l'ouest de Ken-Kol."],
