      fr: ["Nombre de kourganes : 230", "Plus grand kourgane : 15 m de diamètre", "Période d'inhumation : VIIe–IIIe siècle av. J.-C.", "Mobilier funéraire : 45 pointes de flèches en bronze", "Point culminant : 2 100 m d'altitude", "Première fouille : 1958"],
