    facts: {
      de: ["Errichtet im Jahr 1970", "Bronze auf Granitsockel", "Höhe von über 10 Metern", "Wahrzeichen von Bischkek"],
      hu: ["1970-ben állították", "Bronz gránit talapzaton", "Több mint 10 méter magas", "Biskek egyik jelképe"],
      ro: ["Ridicată în anul 1970", "Bronz pe soclu de granit", "Înălțime de peste 10 metri", "Simbol al orașului Bișkek"],
      en: ["Erected in 1970", "Bronze on granite pedestal", "Stands over 10 meters high", "Iconic landmark of Bishkek"],
      es: ["Erigido en el año 1970", "Bronce sobre pedestal de granito", "Altura de más de 10 metros", "Emblema de Biskek"],
      pt: ["Erguido no ano de 1970", "Bronze sobre pedestal de granito", "Altura de mais de 10 metros", "Símbolo de Bisqueque"],
      fr: ["Érigé en 1970", "Bronze sur socle en granit", "Hauteur de plus de 10 mètres", "Symbole de Bichkek"],
    },
    imageHint: "equestrian statue of Mikhail Frunze in Bishkek",
    descriptionAdvanced: {
      de: "Das imposante Reiterdenkmal von Michail Frunze steht prominent auf dem Platz vor dem Hauptbahnhof von Bischkek und ist eines der bekanntesten Wahrzeichen der kirgisischen Hauptstadt. Michail Wassiljewitsch Frunze war ein bedeutender sowjetischer General und Heerführer während des russischen Bürgerkriegs, der 1885 in dieser Stadt geboren wurde, als sie noch Pishpek hieß. Ihm zu Ehren trug Bischkek von 1926 bis 1991 den Namen Frunze. Das Denkmal wurde 1970 eingeweiht und zeigt den General in einer heroischen Pose auf seinem Pferd, gegossen in dunkler Bronze und auf einem massiven Sockel aus rotem Granit platziert. Mit einer Gesamthöhe von über zehn Metern dominiert es die architektonische Achse, die zum Bahnhof führt. Trotz der politischen Veränderungen nach der Unabhängigkeit Kirgisistans blieb die Statue als Teil des historischen Erbes erhalten. Sie ist heute ein beliebter Treffpunkt für Einheimische und ein wichtiges Fotomotiv für Reisende, die sich für die sowjetische Geschichte Zentralasiens interessieren.",
      hu: "Mihail Frunze monumentális lovasszobra Biskek egyik legmeghatározóbb jelképe, amely büszkén áll a város főpályaudvara előtti téren. A szobrot 1970-ben állították a híres szovjet hadvezér emlékére, aki 1885-ben született ebben a városban, amelyet akkoriban még Pishpeknek hívtak. Frunze tiszteletére a város 1926-tól egészen 1991-ig az ő nevét viselte. A több mint 10 méter magas alkotás bronzból készült, és egy robusztus vörös gránit talapzaton nyugszik, hűen tükrözve a szovjet korszak heroikus művészeti stílusát. A tábornokot határozott mozdulattal, lován ülve ábrázolja, mintha éppen szemlét tartana a csapatok felett. A szobor elhelyezkedése szimbolikus, hiszen a vasútállomásra érkező látogatók számára ez az első jelentős látnivaló, amely fogadja őket. Bár az ország függetlenné válása után sok szovjet emlékművet eltávolítottak, Frunze szobra a helyén maradt, mint a város történelmének szerves része és a biskeki identitás fontos eleme.",
      ro: "Statuia ecvestră a lui Mihail Frunze este un simbol arhitectural dominant în Bișkek, fiind situată strategic în piața din fața gării centrale. Monumentul îl onorează pe generalul sovietic Mihail Frunze, una dintre figurile cheie ale Războiului Civil Rus, care s-a născut chiar în acest oraș în anul 1885. Importanța sa istorică este atât de mare încât capitala Kârgâzstanului a purtat numele 'Frunze' timp de 65 de ani, între 1926 și 1991. Inaugurată în 1970, statuia este realizată din bronz masiv și este așezată pe un soclu impunător din granit roșu, atingând o înălțime totală de peste zece metri. Generalul este reprezentat într-o postură demnă, călare, simbolizând autoritatea și legătura sa profundă cu regiunea natală. Monumentul este un exemplu clasic de realism socialist și a supraviețuit perioadei post-sovietice, rămânând un punct de reper important pentru navetiști și turiști deopotrivă. Zona din jurul statuii este adesea animată, servind ca loc de întâlnire și ca punct de plecare pentru explorarea istoriei complexe a Bișkekului.",
      en: "The Frunze Equestrian Monument is one of Bishkek's most prominent landmarks, standing majestically in the square facing the main railway station. Erected in 1970, the bronze statue honors Mikhail Frunze, a high-ranking Soviet military leader born in the city in 1885 back when it was known as Pishpek. His legacy was so significant that the capital itself was renamed Frunze in his honor from 1926 until 1991. The monument features the general on horseback in a heroic pose, mounted on a massive pedestal of polished red granite, reaching a total height of over 10 meters. It serves as a visual anchor for the city's railway gateway, greeting travelers arriving by train with a sense of historic grandeur. Despite the many changes since Kyrgyzstan's independence, the statue remains in its original location, preserved as a piece of the city's complex 20th-century history. For visitors, it offers a prime example of Soviet-era monumental art and a direct link to the namesake of the city's previous identity.",
      es: "La estatua ecuestre de Frunze en la plaza Ala-Too de Biskek muestra al líder militar soviético Mijaíl Frunze. Erigida en 1978, la estatua de bronce mide 9 metros de altura y pesa 10 toneladas. Frunze nació en Biskek, ciudad que llevó su nombre desde 1926 hasta 1991.",
      pt: "A estátua equestre de Frunze na Praça Ala-Too em Bisqueque mostra o líder militar soviético Mikhail Frunze. Erguida em 1978, a estátua de bronze tem 9 metros de altura e pesa 10 toneladas. Frunze nasceu em Bisqueque, que teve o seu nome de 1926 a 1991.",
      fr: "La statue équestre de Frounzé sur la place Ala-Too à Bichkek représente le chef militaire soviétique Mikhaïl Frounzé. Érigée en 1978, la statue en bronze mesure 9 mètres de haut et pèse 10 tonnes. Frounzé est né à Bichkek, qui a porté son nom de 1926 à 1991.",
    },
