    facts: {
      de: ["Beherbergt alte Musikinstrumente", "Toktogul war ein Akyn-Sänger", "Dokumente aus dem Exil", "Gründung im Jahr 1989"],
      hu: ["Régi hangszereket őriz", "Toktogul akün énekes volt", "Dokumentumok a száműzetéséből", "Alapítva 1989-ben"],
      ro: ["Găzduiește instrumente vechi", "Toktogul a fost un cântăreț akyn", "Documente din perioada exilului", "Fondat în anul 1989"],
      en: ["Houses ancient musical instruments", "Toktogul was a famous Akyn singer", "Includes documents from his exile", "Founded in 1989"],
      es: ["Alberga instrumentos musicales antiguos", "Toktogul era un cantante Akyn", "Documentos del exilio", "Fundación en el año 1989"],
      pt: ["Alberga instrumentos musicais antigos", "Toktogul era um cantor Akyn", "Documentos do exílio", "Fundação no ano de 1989"],
      fr: ["Abrite des instruments de musique anciens", "Toktogoul était un chanteur Akyn", "Documents de son exil", "Fondation en 1989"],
    },
    imageHint: "museum of Kyrgyz music and poetry",
    descriptionAdvanced: {
      de: "Das Toktogul-Satylganow-Museum in Bischkek ist eine zentrale Kultureinrichtung, die dem Leben des berühmtesten kirgisischen Barden (Akyn) und Komponisten gewidmet ist. Toktogul Satylganow (1864–1933) gilt als Nationalheld, dessen Werk die mündliche Tradition der kirgisischen Volksmusik in die Moderne überführte. Das Museum beherbergt eine beeindruckende Sammlung von Komuz-Instrumenten – die traditionelle dreisaitige Langhalslaute –, auf denen Toktogul meisterhaft spielte. Die Exponate dokumentieren seinen Widerstand gegen die zaristische Unterdrückung, seine Jahre in der sibirischen Verbannung und seine triumphale Rückkehr in die Heimat. Neben Notenhandschriften und persönlichen Gegenständen bietet das Museum Einblicke in die Kunst der improvisierten Poesie, die in der kirgisischen Kultur tief verwurzelt ist. Es befindet sich in der Nähe der Nationalphilharmonie und dient als wichtiges Forschungszentrum für die Erhaltung des musikalischen Erbes Kirgisistans.",
      hu: "A biskkeki Toktogul Satilganov Múzeum a legjelentősebb kirgiz népköltőnek, zenésznek és akün énekesnek állít emléket. Toktogul (1864–1933) a kirgiz kultúra egyik legmeghatározóbb alakja, aki a hagyományos komuzzene mestereként vált ismertté. A múzeum kiállításai részletesen bemutatják életútját, beleértve az 1898-as cári elnyomás elleni fellépését követő szibériai száműzetését is, ahonnan kalandos úton tért haza. A gyűjteményben számos történelmi hangszert, eredeti kéziratot és korabeli fényképet láthatunk, amelyek a kirgiz nomád művészet és a korai szovjet korszak találkozását dokumentálják. Az intézmény nemcsak egy egyszerű kiállítótér, hanem a kirgiz szellemi örökség őrzőhelye is, ahol a látogatók megismerhetik az improvizatív énekmondás (akün) hagyományát. A múzeum központi elhelyezkedése miatt könnyen elérhető a város kulturális negyedében, a Nemzeti Filharmónia közvetlen szomszédságában.",
      ro: "Muzeul Toktogul Satylganov din Bișkek este o instituție culturală de prim rang dedicată celui mai iubit bard (akyn) și compozitor popular kârgâz. Toktogul Satylganov (1864–1933) este considerat o figură emblematică a identității naționale, opera sa reflectând spiritul de libertate și tradițiile muzicale ale stepei. Muzeul găzduiește o colecție vastă de instrumente komuz originale, lăuta tradițională cu trei corzi la care Toktogul a compus numeroase melodii clasice. Expoziția urmărește parcursul său biografic dramatic, inclusiv perioada de exil în Siberia și evadarea sa spectaculoasă, fapte care l-au transformat într-un erou popular. Vizitatorii pot vedea manuscrise rare, fotografii de epocă și costume tradiționale, oferind o perspectivă profundă asupra evoluției literaturii și muzicii kârgâze în secolul al XX-lea. Situat în apropierea Filarmonicii Naționale, muzeul este un punct esențial pentru oricine dorește să înțeleagă rădăcinile culturale și reziliența poporului kârgâz prin intermediul artei sale sonore.",
      en: "The Toktogul Satylganov Museum in Bishkek is a premier cultural institution dedicated to the life and legacy of Kyrgyzstan's most celebrated folk poet, singer, and composer. Toktogul Satylganov (1864–1933) is a national icon whose mastery of the Komuz—the traditional three-stringed lute—elevated Kyrgyz oral traditions to new heights. The museum showcases an extensive collection of musical instruments, original scores, and personal artifacts that detail his artistic journey. A significant portion of the exhibit is dedicated to his political resistance against Tsarist rule, his subsequent exile to Siberia in 1898, and his daring escape back to his homeland. Through historical documents and recordings, the museum illustrates the evolution of the Akyn tradition (improvisational singing) and its role in preserving Kyrgyz identity. Located near the National Philharmonic building, it serves as both a memorial and a research center for Central Asian ethnomusicology.",
      es: "El Museo Toktogul-Satylganov en Toktogul está dedicado al famoso Akyn (cantante popular) kirguís. Inaugurado en 1966, exhibe objetos personales, instrumentos musicales y manuscritos. Toktogul (1864–1933) influyó profundamente en la música y poesía kirguís.",
      pt: "O Museu Toktogul-Satylganov em Toktogul é dedicado ao famoso Akyn (cantor popular) quirguiz. Inaugurado em 1966, exibe objetos pessoais, instrumentos musicais e manuscritos. Toktogul (1864–1933) moldou a música e a poesia quirguizes.",
      fr: "Le musée Toktogoul Satylganov, à Toktogoul, est consacré au célèbre Akyn (chanteur populaire) kirghize. Ouvert en 1966, il présente des objets personnels, des instruments de musique et des manuscrits. Toktogoul (1864-1933) a marqué la musique et la poésie kirghizes.",
    },
