      hu: ["Három kamrából állnak", "Karahanida uralkodói sírok", "Geometrikus tégla minták", "Jelentős középkori építészet"],
      ro: ["Sunt compuse din trei camere", "Morminte ale regilor Karakhanizi", "Modele geometrice din cărămidă", "Arhitectură medievală importantă"],
      en: ["Consist of three connected chambers", "Tombs of Karakhanid dynasty rulers", "Geometric terracotta brick patterns", "Prime example of medieval architecture"],
      es: ["Constan de tres cámaras", "Tumbas de gobernantes qarajánidas", "Patrones geométricos de ladrillo", "Importante arquitectura medieval"],
      pt: ["Compostos por três câmaras", "Túmulos de governantes caracanidas", "Padrões geométricos de tijolo", "Arquitetura medieval significativa"],
