      en: "Ruins of a medieval settlement in the Chuy Valley. Archaeological finds indicate an advanced craft culture dating from the 9th to 12th centuries.",
      es: "Ruinas de un asentamiento medieval en el valle de Chuy. Los hallazgos arqueológicos indican una cultura artesanal avanzada entre los siglos IX y XII.",
      pt: "Ruínas de um povoado medieval no Vale de Chuy. Achados arqueológicos indicam uma cultura artesanal avançada entre os séculos IX e XII.",
