    imageHint: "archaeological ruins of medieval settlement",
    descriptionAdvanced: {
      de: "Die Ak-Terek-Siedlung ist eine bedeutende archäologische Stätte im fruchtbaren Tschui-Tal, die wertvolle Einblicke in die sesshafte Kultur Zentralasiens zwischen dem 9. und 12. Jahrhundert bietet. Die Ruinen stammen vorwiegend aus der Ära der Karachaniden, einer Zeit, in der das Handwerk und der Handel entlang der Seidenstraße florierten. Archäologische Ausgrabungen haben eine hoch entwickelte metallverarbeitende Industrie sowie zahlreiche Keramiköfen freigelegt, was Ak-Terek als ein regionales Zentrum für Produktion und Gewerbe kennzeichnet. Die Siedlungsstruktur lässt auf eine geplante urbane Entwicklung mit Wohn- und Werkstattbereichen schließen. Heute befinden sich die Überreste in der Nähe der Stadt Sokuluk und stellen ein wichtiges Zeugnis für die historische Transformation der Region von nomadischen Lebensweisen zu festen städtischen Strukturen dar. Die Funde von Alltagsgegenständen und Werkzeugen verdeutlichen das handwerkliche Geschick der damaligen Bewohner.",
      hu: "Az Ak-Terek település a Csuj-völgy egyik kiemelkedő régészeti lelőhelye, amely a 9. és 12. század közötti középkori életmódról tanúskodik. A romok nagy része a Karahanida-dinasztia korszakából származik, amikor a Selyemút mentén virágzott a kézművesség és a kereskedelem. A feltárások során fejlett fémmegmunkáló műhelyeket és kerámiaégető kemencéket azonosítottak, ami arra utal, hogy Ak-Terek fontos ipari és gazdasági központ volt a régióban. A település szerkezete jól mutatja a korabeli városfejlesztési elveket, elkülönülő lakó- és ipari zónákkal. A Szokuluk városa közelében található rommező fontos láncszeme Kirgizisztán történelmének, segítve a kutatókat a nomád és a letelepedett kultúrák közötti átmenet megértésében. Az itt talált kerámiatöredékek és szerszámok a korabeli mesteremberek magas szintű tudásáról és a völgy gazdasági jelentőségéről mesélnek az idelátogatóknak.",
      ro: "Așezarea Ak-Terek constituie un sit arheologic de primă importanță situat în Valea Chuy, oferind o fereastră spre civilizația sedentară din Asia Centrală între secolele IX și XII. Ruinele aparțin în principal epocii Karakhanide, o perioadă de efervescență culturală și economică facilitată de rutele Drumului Mătăsii. Cercetările au scos la iveală dovezi ale unei industrii metalurgice sofisticate și cuptoare antice pentru arderea ceramicii, confirmând rolul de centru meșteșugăresc al locației. Planimetria așezării indică o organizare urbană complexă, cu zone dedicate producției și spații rezidențiale distincte. Situat în proximitatea orașului Sokuluk, situl Ak-Terek documentează tranziția istorică a populațiilor locale de la nomadism la o viață urbană structurată. Artefactele descoperite aici, de la unelte la obiecte de uz casnic, demonstrează nivelul tehnic ridicat al artizanilor medievali și importanța strategică a văii în acea perioadă.",
      en: "The Ak-Terek Settlement is a significant archaeological site located in the fertile Chuy Valley, providing crucial insights into the sedentary cultures of Central Asia from the 9th to the 12th centuries. Predominantly associated with the Karakhanid era, the ruins reflect a period when craftsmanship and trade flourished along the Silk Road. Excavations have revealed sophisticated metalworking sites and ancient ceramic kilns, establishing Ak-Terek as a vital regional hub for production and industry. The layout of the settlement suggests a well-organized urban structure with distinct residential and workshop areas. Situated near the modern town of Sokuluk, the remains serve as an essential record of the historical transition from nomadic lifestyles to established urban centers in Kyrgyzstan. The diverse finds of tools and pottery highlight the technical skill of the medieval inhabitants and the economic importance of this trade route settlement.",
      es: "El asentamiento de Ak-Terek, en el valle de Chuy, fue una ciudad fortificada de los siglos VI al X. Las excavaciones descubrieron una ciudadela, barrios residenciales y talleres artesanales. La ciudad estaba situada en una ruta secundaria de la Ruta de la Seda y comerciaba con textiles y metales.",
      pt: "O povoado de Ak-Terek, no Vale de Chuy, foi uma cidade fortificada dos séculos VI a X. As escavações revelaram uma cidadela, bairros residenciais e oficinas de artesanato. A cidade situava-se num caminho secundário da Rota da Seda e comerciava têxteis e metais.",
      fr: "L'établissement d'Ak-Terek, dans la vallée de Tchouï, était une ville fortifiée du VIe au Xe siècle. Les fouilles ont mis au jour une citadelle, des quartiers résidentiels et des ateliers artisanaux. La ville était située sur une route secondaire de la Route de la Soie et faisait le commerce de textiles et de métaux.",
    },
