      es: ["Construida: siglos VIII-XII", "Superficie: 2 hectáreas", "Altura de muros: hasta 6 m", "Torres: 4 conservadas", "Altitud: 1.800 m sobre el nivel del mar", "Excavaciones desde 1980"],
      pt: ["Construída: séculos VIII-XII", "Área: 2 hectares", "Altura das muralhas: até 6 m", "Torres: 4 conservadas", "Altitude: 1.800 m acima do nível do mar", "Escavações desde 1980"],
      fr: ["Construite : VIIIe-XIIe siècle", "Surface : 2 hectares", "Hauteur des murs : jusqu'à 6 m", "Tours : 4 conservées", "Altitude : 1 800 m d'altitude", "Fouilles depuis 1980"],
