    parent: "KG",
    type: "landmark",
    name: { de: "Kulan-Say-Petroglyphen", hu: "Kulan-Szaj petroglifák", ro: "Petroglifele Kulan-Say", en: "Kulan-Say Rock Art" },
    coords: [72.1511, 42.4511],
    description: {
      de: "Eine Ansammlung von Felsritzungen im Talas-Gebirge, die Tiere und Symbole aus der Bronze- und Eisenzeit darstellen. Sie sind ein wichtiges Zeugnis früher Kulturen.",
      hu: "Sziklarajzok gyűjteménye a Talasz-hegységben, amelyek bronz- és vaskori állatokat és szimbólumokat ábrázolnak. Fontos emlékek a korai kultúrákról.",
      ro: "O colecție de desene pe stâncă în munții Talas, reprezentând animale și simboluri din epoca bronzului și a fierului. Sunt o dovadă a culturilor timpurii.",
      en: "A collection of rock carvings in the Talas Mountains depicting Bronze and Iron Age animals and symbols. They are a significant record of early cultures.",
      es: "Un conjunto de grabados rupestres en las montañas de Talas que representan animales y símbolos de la Edad del Bronce y del Hierro. Son un testimonio importante de las culturas antiguas.",
      pt: "Um conjunto de gravuras rupestres nas montanhas de Talas que representam animais e símbolos da Idade do Bronze e do Ferro. São um testemunho importante de culturas antigas.",
      fr: "Un ensemble de gravures rupestres dans les montagnes de Talas, représentant des animaux et des symboles de l'âge du bronze et du fer. Elles sont un témoignage important des cultures anciennes.",
    },
    facts: {
      de: ["Über 500 Zeichnungen", "Darstellung von Wildeseln", "Bronzezeitliche Ursprünge", "Jagdszenen mit Bogen"],
      hu: ["Több mint 500 rajz", "Vadszamarak ábrázolása", "Bronzkori eredet", "Íjas vadászjelenetek"],
      ro: ["Peste 500 de desene", "Reprezentări de măgari sălbatici", "Origini din epoca bronzului", "Scene de vânătoare cu arcul"],
      en: ["Over 500 individual drawings", "Depict wild asses (kulans)", "Bronze Age origins", "Hunting scenes with bows"],
      es: ["Más de 500 dibujos", "Representación de asnos salvajes", "Orígenes en la Edad del Bronce", "Escenas de caza con arco"],
      pt: ["Mais de 500 desenhos", "Representação de burros selvagens", "Origens na Idade do Bronze", "Cenas de caça com arco"],
      fr: ["Plus de 500 dessins", "Représentation d'ânes sauvages", "Origines de l'âge du Bronze", "Scènes de chasse à l'arc"],
    },
    imageHint: "ancient petroglyphs on dark mountain rocks",
    descriptionAdvanced: {
      de: "Die Kulan-Say-Petroglyphen befinden sich im malerischen Talas-Gebirge im Nordwesten Kirgisistans und stellen eine der bedeutendsten Fundstätten prähistorischer Felskunst in Zentralasien dar. Über 500 einzelne Zeichnungen sind auf den dunklen, von der Sonne patinierten Felsen verteilt und stammen vorwiegend aus der Bronze- und frühen Eisenzeit. Der Name des Ortes leitet sich vom 'Kulan' ab, dem asiatischen Wildesel, der in vielen der Abbildungen detailgetreu dargestellt ist. Neben den Kulans finden sich Motive von Hirschen, Ziegen und heroischen Jagdszenen, in denen Krieger mit Bögen und Hunden agieren. Die Künstler nutzten eine Picktechnik, um die hellere Steinschicht unter der dunklen Oberfläche freizulegen, was den Bildern bis heute eine bemerkenswerte Klarheit verleiht. Kulan-Say bietet Archäologen wertvolle Informationen über die Fauna der Region vor Jahrtausenden sowie über das Weltbild und die Lebensweise der frühen nomadischen Stämme. Für Reisende ist das Tal ein faszinierendes Open-Air-Museum, das die tiefe Verbindung zwischen Mensch und Natur in dieser rauen Gebirgswelt dokumentiert.",
      hu: "A Kulan-Szaj sziklarajzok Kirgizisztán északnyugati részén, a Talasz-hegység egyik völgyében találhatók, és Közép-Ázsia egyik legfontosabb régészeti lelőhelyét alkotják. A gyűjtemény több mint 500 egyedi petroglifát tartalmaz, amelyek többsége a bronzkorból és a kora vaskorból származik. A helyszín nevét a 'kulánról', az ázsiai vadszamárról kapta, amely visszatérő motívum a sötét sziklákon; az állatokat gyakran mozgás közben, élethűen ábrázolták az őskori művészek. A rajzok között láthatók még kőszáli kecskék, szarvasok, valamint összetett vadászjelenetek, ahol íjjal felfegyverzett alakok és kutyák is megjelennek. A petroglifák készítői a sötét kőzetfelszínt pattintották le, hogy láthatóvá váljon az alatta lévő világosabb réteg, így teremtve tartós és kontrasztos képeket. Kulan-Szaj nemcsak művészeti értékkel bír, hanem kulcsfontosságú forrás a nomád népek hitvilágának, öltözködésének és fegyverzetének megismeréséhez. A terület látogatása különleges időutazást ígér a vadregényes hegyi tájban, ahol az ősi kövek ma is őrzik az évezredekkel ezelőtti élet nyomait.",
      ro: "Petroglifele de la Kulan-Say reprezintă una dintre cele mai valoroase moșteniri preistorice ale Kârgâzstanului, fiind situate în Munții Talas, într-o zonă de o frumusețe naturală austeră. Situl cuprinde peste 500 de gravuri rupestre ce datează în principal din epoca bronzului și prima epocă a fierului. Denumirea provine de la 'kulan', măgarul sălbatic asiatic, animal care apare frecvent în compozițiile artistice, alături de ibexi, căprioare și lupi. Desenele au fost realizate prin tehnica percuției pe fețele întunecate ale stâncilor, creând un contrast vizibil cu interiorul mai deschis al pietrei. Scenele de vânătoare sunt deosebit de detaliate, înfățișând bărbați cu arcuri și câini, oferind indicii prețioase despre tehnicile de supraviețuire ale triburilor nomade timpurii. De asemenea, se pot observa simboluri solare și figuri antropomorfe ce sugerează practici șamanice sau ritualuri de fertilitate. Kulan-Say servește ca o galerie de artă în aer liber și ca un document istoric vital, ajutând cercetătorii să reconstruiască fauna și mediul social al Asiei Centrale de acum trei milenii.",
      en: "The Kulan-Say Rock Art site, nestled in the Talas Mountains of northwestern Kyrgyzstan, is a significant archaeological treasure featuring over 500 petroglyphs. Most of these carvings date back to the Bronze and early Iron Ages, providing a vivid record of the region's ancient inhabitants. The site is named after the 'kulan,' an Asian wild ass that is a recurring subject in the rock art, often depicted with remarkable anatomical accuracy. Beyond the kulans, the dark, sun-scorched rocks are etched with images of mountain goats, stags, and dynamic hunting scenes involving bow-wielding archers and their dogs. These petroglyphs were created by pecking away the dark surface patina to reveal the lighter stone beneath, a technique that has allowed the images to endure for thousands of years. Kulan-Say offers a unique window into the spiritual world, hunting practices, and social structures of early nomadic cultures. Exploring the valley provides an immersive experience where history and nature converge, revealing the long-standing human connection to the high-altitude landscapes of Central Asia.",
      es: "Kulan-Say, en las montañas de Tian Shan, alberga grabados rupestres de la Edad del Bronce (II milenio a.C.). Más de 1.000 petroglifos muestran animales, cazadores y escenas rituales. Las imágenes grabadas miden hasta 50 cm y ofrecen información sobre el mundo de creencias de los nómadas.",
      pt: "Kulan-Say, nas montanhas Tian Shan, alberga gravuras rupestres da Idade do Bronze (II milénio a.C.). Mais de 1.000 petroglifos mostram animais, caçadores e cenas rituais. As imagens gravadas têm até 50 cm e oferecem visões sobre o mundo das crenças dos nómadas.",
      fr: "Kulan-Say, dans les montagnes du Tian Shan, abrite des gravures rupestres de l'âge du bronze (IIe millénaire av. J.-C.). Plus de 1 000 pétroglyphes représentent des animaux, des chasseurs et des scènes rituelles. Les images gravées mesurent jusqu'à 50 cm et donnent un aperçu du monde spirituel des nomades.",
    },
