      en: ["Number of rock drawings: 700", "Period: 1st millennium BCE", "Largest scene: 2 m wide", "Chariots depicted: 12", "Elevation: 2,500 m", "Research since 1978"],
      es: ["Número de grabados: 700", "Período: primer milenio a.C.", "Escena más grande: 2 m de ancho", "Carros representados: 12", "Altitud: 2.500 m", "Investigación: desde 1978"],
