    coords: [72.9811, 40.7111],
    description: {
      de: "Antike Petroglyphen im Gebiet Osch, die das tägliche Leben und die religiösen Vorstellungen früher Völker illustrieren. Sie erstrecken sich über mehrere Felswände.",
      hu: "Ősi petroglifák az Osi területen, amelyek a korai népek mindennapi életét és vallási elképzeléseit szemléltetik. Számos sziklafalon elszórva találhatók.",
      ro: "Petroglife antice în regiunea Osh care ilustrează viața de zi cu zi și credințele religioase ale popoarelor timpurii. Se întind pe mai mulți pereți de stâncă.",
      en: "Ancient petroglyphs in the Osh region illustrating the daily life and religious beliefs of early peoples. They are spread across several rock faces.",
      es: "Petroglifos antiguos en la región de Osh que ilustran la vida cotidiana y las creencias religiosas de los pueblos primitivos. Se extienden por varias paredes rocosas.",
      pt: "Pinturas rupestres antigas na região de Osh, que ilustram a vida quotidiana e as crenças religiosas de povos primitivos. Estendem-se por várias paredes de rocha.",
      fr: "Pétroglyphes anciens dans la région d'Och, illustrant la vie quotidienne et les croyances religieuses des premiers peuples. Ils s'étendent sur plusieurs parois rocheuses.",
    },
    facts: {
      de: ["Darstellung von Kamelen", "Antike Sonnenymbole", "Rituelle Tanzszenen", "Eisenzeitliche Datierung"],
      hu: ["Teve ábrázolások", "Ősi nap-szimbólumok", "Rituális táncjelenetek", "Vaskori datálás"],
      ro: ["Reprezentări de cămile", "Simboluri solare antice", "Scene de dans ritualic", "Datate în epoca fierului"],
      en: ["Depictions of camels", "Ancient sun symbols", "Ritual dance scenes", "Dated to the Iron Age"],
      es: ["Representación de camellos", "Antiguos símbolos solares", "Escenas de danzas rituales", "Datación de la Edad del Hierro"],
      pt: ["Representação de camelos", "Símbolos solares antigos", "Cenas de danças rituais", "Datação da Idade do Ferro"],
      fr: ["Représentation de chameaux", "Anciens symboles solaires", "Scènes de danses rituelles", "Datation de l'âge du fer"],
    },
    imageHint: "ancient carvings of camels on rock",
    descriptionAdvanced: {
      de: "Die Karasuu-Felszeichnungen im Gebiet Osch gehören zu den bedeutendsten archäologischen Fundstätten im Süden Kirgisistans. Diese Petroglyphen wurden über Jahrtausende hinweg von verschiedenen nomadischen Kulturen in den dunklen Wüstenlack der Felswände geritzt. Die Darstellungen reichen von der Bronzezeit bis in die frühe Eisenzeit und zeigen eine erstaunliche Vielfalt an Motiven: von majestätischen Kamelen und Hirschen bis hin zu komplexen Jagdszenen. Besonders hervorzuheben sind die zahlreichen Sonnensymbole und rituellen Tänze, die tiefe Einblicke in die spirituelle Weltanschauung der frühen Steppenvölker geben. Forscher interpretieren die Fundstelle als einen ehemaligen rituellen Versammlungsort, an dem astronomische Beobachtungen und religiöse Zeremonien stattfanden. Die trockene Luft der Region hat dazu beigetragen, dass die Linienführung der Zeichnungen bis heute außergewöhnlich scharf geblieben ist, was sie zu einem wertvollen Zeugnis der zentralasiatischen Geschichte macht.",
      hu: "A Karaszu sziklarajzok az Osi terület délkeleti részén találhatók, és Kirgizisztán egyik leggazdagabb petroglifa-gyűjteményét őrzik. A sziklafalakra vésett alkotások több korszakot ölelnek fel, a bronzkortól egészen a korai vaskorig, bemutatva a térségben élt nomád népek művészeti és vallási fejlődését. A rajzokon leggyakrabban tevék, hegyi kecskék és szarvasok láthatók, de a legérdekesebbek azok a jelenetek, amelyek rituális táncokat és áldozati szertartásokat ábrázolnak. Az ősi nap-szimbólumok jelenléte arra utal, hogy a helyszín szakrális jelentőséggel bírt, és talán csillagászati megfigyelésekre is használták. A vaskori datálású metszetek precizitása lenyűgöző; a vonalak mélysége és dinamikája a korabeli kézművesek nagyfokú szakértelméről tanúskodik. A látogatók számára a helyszín nemcsak régészeti élményt nyújt, hanem lehetőséget ad arra is, hogy elmerüljenek a közép-ázsiai sztyeppei civilizációk elfeledett mindennapjaiban.",
      ro: "Desenele rupestre din Karasuu, situate în regiunea Osh din Kârgâzstan, constituie un ansamblu arheologic de o importanță excepțională pentru înțelegerea culturilor nomade timpurii. Aceste petroglife, realizate pe parcursul a mai multor milenii, începând din epoca bronzului și continuând în epoca fierului, sunt incizate în stratul de oxid de pe suprafața stâncilor. Repertoriul iconografic este vast, incluzând reprezentări detaliate de cămile, cerbi și scene de vânătoare colectivă care reflectă dependența comunităților antice de fauna locală. Un aspect distinctiv îl reprezintă simbolurile solare și figurile antropomorfe angajate în dansuri ritualice, sugerând că zona servea drept sanctuar în aer liber pentru practici șamanice. Calitatea conservării este remarcabilă, liniile fiind clare și expresive în ciuda expunerii la intemperii. Situl oferă o fereastră rară către viața spirituală și socială a popoarelor din Asia Centrală, fiind o destinație esențială pentru pasionații de istorie veche și artă preistorică.",
      en: "The Karasuu Rock Drawings, located in the Osh region, represent one of the most significant petroglyph sites in southern Kyrgyzstan. Spread across numerous rock faces, these ancient artworks date back primarily to the Iron Age, though some carvings originate from the earlier Bronze Age. The drawings provide a vivid pictorial record of the nomadic tribes that once traversed the Fergana Valley. Visitors can identify depictions of Bactrian camels, mountain goats, and intricate hunting scenes that showcase the survival strategies of early peoples. Beyond mere daily life, the petroglyphs feature ancient sun symbols and figures in ritualistic dance poses, pointing to the site's importance as a sacred gathering place for religious ceremonies. The precision of the carvings into the dark rock patina allows for a detailed study of ancient artistic techniques. As an open-air museum of Central Asian prehistory, the Karasuu site offers profound insights into the spiritual beliefs and environmental interactions of ancient steppe civilizations.",
      es: "Los petroglifos de Karasuu en el óblast de Osh datan del II al I milenio a.C. Muestran patrones geométricos, figuras de animales y siluetas humanas. Los dibujos están grabados en las paredes rocosas y documentan la evolución del arte nómada.",
      pt: "As pinturas rupestres de Karasuu no Oblast de Osh datam do II ao I milénio a.C. Mostram padrões geométricos, figuras de animais e silhuetas humanas. Os desenhos estão gravados nas paredes rochosas e documentam o desenvolvimento da arte nómada.",
      fr: "Les pétroglyphes de Karassou dans l'oblast d'Och datent du IIe au Ier millénaire avant J.-C. Ils présentent des motifs géométriques, des figures animales et des silhouettes humaines. Les dessins sont gravés dans les parois rocheuses et documentent l'évolution de l'art nomade.",
    },
