      es: ["Periodo de existencia: siglos VI-VIII", "Superficie: 4 hectáreas", "Canales de riego: 3 km de largo", "Graneros: 10 descubiertos", "Tamaño promedio de las casas: 50 m²", "Excavación: desde 1995"],
      pt: ["Período de existência: séculos VI-VIII", "Área: 4 hectares", "Canais de irrigação: 3 km de comprimento", "Celeiros: 10 descobertos", "Tamanho médio das casas: 50 m²", "Escavação: desde 1995"],
      fr: ["Période d'existence : VIe-VIIIe siècle", "Superficie : 4 hectares", "Canaux d'irrigation : 3 km de long", "Greniers : 10 découverts", "Taille moyenne des maisons : 50 m²", "Fouilles : depuis 1995"],
