      pt: "Um sítio arqueológico que compreende vestígios de uma cidade do século VI ao XII. Foi um importante nó para o comércio de seda e especiarias.",
      fr: "Un site archéologique qui comprend les vestiges d'une ville du VIe au XIIe siècle. C'était un carrefour important pour le commerce de la soie et des épices.",
