      es: ["Periodo de existencia: siglos X-XII", "Superficie: 5 hectáreas", "Altura de la ciudadela: 8 m", "Hornos de cerámica: 6 encontrados", "Cerámica vidriada: 300 fragmentos", "Excavación: 1972"],
