    parent: "KG",
    type: "ruins",
    name: { de: "Chon-Dalin-Komplex", hu: "Cson-Dalin komplexum", ro: "Complexul Chon-Dalin", en: "Chon-Dalin Archaeological Complex" },
    coords: [74.5511, 42.8811],
    description: {
      de: "Dieser Komplex am Rande von Bischkek beherbergt Überreste aus der Zeit des Westlichen Türkischen Khaganats. Er umfasst Festungsreste und Grabanlagen.",
      hu: "Ez a biskeki külvárosban található komplexum a Nyugati Türk Kaganátus idejéből származó maradványokat őriz. Erődmaradványokat és sírokat tartalmaz.",
      ro: "Acest complex de la periferia Bișkekului găzduiește vestigii din perioada Kaganatului Turcic Occidental. Include resturi de fortificații și morminte.",
      en: "This complex on the outskirts of Bishkek houses remains from the Western Turkic Khaganate period. It includes fortress foundations and burial sites.",
      es: "Este complejo a las afueras de Biskek alberga restos de la época del Kanato Turco Occidental. Incluye ruinas de fortificaciones y yacimientos funerarios.",
      pt: "Este complexo nos arredores de Bisqueque abriga vestígios da época do Canato Turco Ocidental. Inclui restos de fortificações e complexos funerários.",
      fr: "Ce complexe à la périphérie de Bichkek abrite des vestiges de l'époque du Khaganat turc occidental. Il comprend des restes de fortifications et des sites funéraires.",
    },
    facts: {
      de: ["Datiert auf 7. bis 8. Jh.", "Strategische Verteidigungslage", "Türkische Steinstatuen", "Teil der UNESCO-Kandidatur"],
      hu: ["A 7-8. századra datálható", "Stratégiai védelmi helyzet", "Türk kőszobrok", "UNESCO jelölt helyszín"],
      ro: ["Datat în secolele VII-VIII", "Poziție strategică de apărare", "Statui turcice din piatră", "Parte a candidaturii UNESCO"],
      en: ["Dated to 7th-8th century", "Strategic defensive location", "Turkic stone statues found", "Part of UNESCO nomination list"],
      es: ["Datado en los siglos VII y VIII", "Ubicación estratégica defensiva", "Estatuas de piedra turcas", "Parte de la candidatura de la UNESCO"],
      pt: ["Datado dos séculos VII a VIII", "Localização estratégica de defesa", "Estátuas de pedra turcas", "Parte da candidatura à UNESCO"],
      fr: ["Daté des VIIe et VIIIe siècles", "Position défensive stratégique", "Statues de pierre turques", "Fait partie de la candidature à l'UNESCO"],
    },
    imageHint: "ancient Turkic stone foundations",
    descriptionAdvanced: {
      de: "Der archäologische Komplex Chon-Dalin, gelegen am nordöstlichen Rand der kirgisischen Hauptstadt Bischkek, ist ein bedeutendes Zeugnis der frühmittelalterlichen Geschichte Zentralasiens. Die Fundstätte wird dem Westlichen Türkischen Khaganat zugerechnet und datiert etwa in das 7. bis 8. Jahrhundert nach Christus. Besonders eindrucksvoll sind die Überreste einer einstigen Festungsanlage, die strategisch günstig am Hang positioniert war, um die Handelsrouten der Seidenstraße zu überwachen. Ein herausragendes Merkmal von Chon-Dalin sind die aufgefundenen 'Balbals' – anthropomorphe Steinstatuen, die oft zu Ehren gefallener Krieger errichtet wurden und typisch für die nomadische Kultur der Turkvölker sind. Die Ausgrabungen haben zudem komplexe Grabanlagen und Keramikreste freigelegt, die wertvolle Rückschlüsse auf die soziale Struktur und das religiöse Leben der damaligen Bewohner zulassen. Als Teil einer größeren Initiative zur Anerkennung des kulturellen Erbes steht die Stätte auf der Kandidatenliste für das UNESCO-Welterbe.",
      hu: "A Cson-Dalin régészeti komplexum Biskek peremkerületében található, és Közép-Ázsia kora középkori történelmének egyik legfontosabb lelőhelye Kirgizisztánban. A terület a 7. és 8. század között virágzó Nyugati Türk Kaganátus idejéből származik, amikor a régió a Selyemút egyik kulcsfontosságú csomópontja volt. A feltárások során egykori erődítmények alapjait, védműveket és lakóépületeket azonosítottak, amelyek egy jól szervezett katonai és közigazgatási központról tanúskodnak. A helyszín különlegességét a 'balbalok' adják – ezek olyan faragott kőszobrok, amelyeket a türk törzsek állítottak elhunyt elődeik vagy hőseik tiszteletére. A komplexum nemcsak védelmi célokat szolgált, hanem fontos rituális helyszín is volt, amit a feltárt sírhalmok gazdag leletanyaga is bizonyít. Chon-Dalin jelenleg az UNESCO világörökségi várományosi listáján szerepel, mint a Selyemút kirgizisztáni szakaszának egyik kiemelkedő állomása.",
      ro: "Complexul arheologic Chon-Dalin, situat la periferia nord-estică a orașului Bișkek, reprezintă o fereastră prețioasă spre epoca de aur a Kaganatului Turcic Occidental. Datând din secolele VII-VIII, acest sit a servit drept punct strategic de apărare și control pe rutele comerciale ale Drumului Mătăsii. Vestigiile includ fundații de fortificații masive și zone rezidențiale care demonstrează avansul arhitectural al perioadei. Elementul cel mai fascinant al complexului îl reprezintă statuile din piatră numite 'balbals', figuri antropomorfe sculptate cu mare atenție, care aveau un rol funerar și comemorativ specific culturilor nomade turcice. Săpăturile au scos la iveală și numeroase obiecte din ceramică și unelte, oferind detalii despre viața cotidiană a garnizoanelor și a populației civile. Datorită valorii sale istorice excepționale, complexul Chon-Dalin face parte din seria de situri nominalizate pentru includerea în Patrimoniul Mondial UNESCO, fiind esențial pentru înțelegerea migrațiilor și a structurilor statale timpurii din Asia Centrală.",
      en: "The Chon-Dalin Archaeological Complex, positioned on the outskirts of Bishkek, is a significant historical site dating back to the 7th and 8th centuries during the reign of the Western Turkic Khaganate. This complex served as a vital defensive stronghold along the Silk Road, providing protection and oversight for the merchant caravans traversing the region. The site features the foundations of ancient fortresses and burial mounds that offer deep insights into the military and social hierarchy of the early medieval Turkic peoples. Perhaps most striking are the 'balbals'—stone statues carved with human features, erected to honor fallen warriors or ancestors, which are iconic to the nomadic cultures of Central Asia. Archaeological research here has yielded a wealth of ceramics and artifacts that reveal the complex trade links and religious practices of the time. Currently part of the UNESCO tentative list, Chon-Dalin remains a crucial site for understanding the transitional history between the nomadic world and the rising urban centers of the Silk Road.",
      es: "El complejo arqueológico Chon-Dalin, en el óblast de Naryn, comprende un asentamiento y túmulos funerarios de los siglos VIII al III a.C. Los hallazgos demuestran una cultura sedentaria con ganadería y agricultura. La cerámica muestra influencias del valle de Ferganá.",
      pt: "O complexo arqueológico Chon-Dalin, no Oblast de Naryn, compreende um povoado e túmulos dos séculos VIII a III a.C. Os achados comprovam uma cultura sedentária com pecuária e agricultura. A cerâmica mostra influências do Vale de Fergana.",
      fr: "Le complexe archéologique Chon-Dalin, dans l'oblast de Naryn, comprend un établissement et des tumulus datant du VIIIe au IIIe siècle avant J.-C. Les découvertes témoignent d'une culture sédentaire pratiquant l'élevage et l'agriculture. La céramique montre des influences de la vallée de Ferghana.",
    },
