      hu: "Ezeket a magashegyi legelőket évezredek óta használták a nomádok nyári szállásként. A történelmi táborhelyek ősi tűzhelyek nyomait mutatják.",
      ro: "Aceste pășuni montane înalte au fost folosite de nomazi ca pășuni de vară timp de milenii. Locurile de tabără istorice arată urme de vetre vechi.",
      en: "These high-altitude meadows have been used by nomads as summer pastures for millennia. Historic camp sites show traces of ancient hearths.",
