    imageHint: "Ala-Too cinema building in Bishkek",
    descriptionAdvanced: {
      de: "Das Ala-Too Kino-Gebäude im Herzen von Bischkek ist ein markantes Wahrzeichen der kirgisischen Hauptstadt und ein bedeutendes Denkmal der sowjetischen Architektur. Eröffnet im Jahr 1938, war es das erste moderne Großkino des Landes und wurde schnell zum kulturellen Mittelpunkt der Stadt. Die Fassade des Gebäudes ist im Stil des sozialistischen Klassizismus gestaltet und mit kunstvollen Reliefs und Motiven geschmückt, die die sowjetische Ideologie und die lokale Kultur der Vorkriegszeit widerspiegeln. Direkt am Prospekt Tschui gelegen, der Hauptverkehrsader Bischkeks, hat das Gebäude zahlreiche historische Umbrüche miterlebt und ist bis heute ein beliebter Treffpunkt geblieben. Trotz Modernisierungen im Inneren wurde das äußere Erscheinungsbild sorgfältig bewahrt, um den historischen Charakter zu schützen. Ein Besuch des Kinos bietet nicht nur filmische Unterhaltung, sondern auch eine Reise in die architektonische Vergangenheit der Sowjetunion, eingebettet in das pulsierende Leben des modernen Kirgisistans.",
      hu: "Az Ala-Too mozi épülete Biskek központjában található, és Kirgizisztán egyik legfontosabb szovjet korszakból származó építészeti emléke. Az 1938-ban megnyitott mozi volt az ország első olyan intézménye, amelyet kifejezetten szélesvásznú filmek vetítésére terveztek, és hamar a főváros kulturális életének szívévé vált. A homlokzatot a sztálini klasszicizmus stílusjegyei díszítik, különös tekintettel azokra a finom domborművekre, amelyek a kor szellemiségét és a népi motívumokat ötvözik. Az épület a Csuj sugárúton, a város legforgalmasabb pontján áll, és máig megőrizte eredeti funkcióját, miközben műemléki védettséget élvez. A mozi nem csupán a szórakozás helyszíne, hanem egyfajta időkapszula is, amely emlékeztet Biskek háború előtti fejlődésére és a szovjet modernizáció korszakára. A turisták számára az épület lenyűgöző fotótémát és hiteles betekintést nyújt a város történelmi szövetébe.",
      ro: "Clădirea Cinematografului Ala-Too este o emblemă culturală și arhitecturală situată în centrul orașului Bișkek, capitala Kârgâzstanului. Inaugurat în anul 1938, acesta a fost primul cinematograf modern din regiune, devenind rapid punctul central de întâlnire pentru iubitorii de artă din perioada sovietică prebelică. Arhitectura clădirii este un exemplu clasic de realism socialist, evidențiindu-se prin fațada sa impunătoare decorată cu reliefuri și motive ornamentale ce reflectă atât estetica sovietică, cât și elemente din cultura locală kârgâză. Situat strategic pe Bulevardul Chuy, cinematograful a supraviețuit deceniilor de schimbări politice, păstrându-și farmecul original și statutul de monument istoric protejat. Deși dotările interioare au fost modernizate pentru a corespunde standardelor actuale, exteriorul rămâne neschimbat, oferind trecătorilor o lecție vizuală de istorie urbană. Este un loc simbolic care îmbină nostalgia erei trecute cu dinamismul vieții contemporane din Bișkek.",
      en: "The Ala-Too Cinema building is a prominent landmark in the heart of Bishkek and a significant monument of Kyrgyzstan's architectural heritage. Opened in 1938, it holds the distinction of being the city's oldest cinema and was the first building in the republic specifically designed for high-quality film screenings. Its architecture reflects the pre-war Soviet style, characterized by a grand neoclassical facade adorned with intricate stuccowork and decorative motifs that blend Soviet iconography with traditional Kyrgyz patterns. Located on Chuy Avenue, the city's main thoroughfare, the cinema has remained a central cultural hub for generations of residents. Throughout the years, it has witnessed the transformation of Bishkek from a provincial town into a modern capital. Recognized as a statutory monument of culture, the Ala-Too Cinema is not only a place to watch movies but also a historic site that offers a glimpse into the artistic and social history of the mid-20th century in Central Asia.",
      es: "El cine Ala-Too en Bishkek es un hito cultural de la era soviética. Se inauguró en 1954 y fue el primer cine de gran formato en Kirguistán. El edificio, de estilo neoclásico, cuenta con un gran auditorio y un escenario. Sirvió como lugar para proyecciones de películas, conciertos y asambleas políticas. Tras la independencia, se deterioró cada vez más, pero fue restaurado en 2018. Hoy proyecta tanto películas internacionales como producciones kirguisas. El cine es un símbolo de la cultura cinematográfica del país.",
      pt: "O cinema Ala-Too em Bishkek é um marco cultural da era soviética. Foi inaugurado em 1954 e foi o primeiro cinema de grande formato no Quirguistão. O edifício de estilo neoclássico possui um grande auditório e um palco. Serviu como local para exibições de filmes, concertos e assembleias políticas. Após a independência, deteriorou-se progressivamente, mas foi restaurado em 2018. Hoje exibe tanto filmes internacionais como produções quirguizes. O cinema é um símbolo da cultura cinematográfica do país.",
      fr: "Le cinéma Ala-Too à Bishkek est un monument culturel de l'époque soviétique. Inauguré en 1954, il fut le premier cinéma grand format du Kirghizistan. Le bâtiment de style néoclassique dispose d'une grande salle d'audience et d'une scène. Il servait de lieu de projections de films, de concerts et de rassemblements politiques. Après l'indépendance, il tomba de plus en plus en ruine, mais fut restauré en 2018. Aujourd'hui, il projette aussi bien des films internationaux que des productions kirghizes. Le cinéma est un symbole de la culture cinématographique du pays.",
    },
