    imageHint: "historic building of Kyrgyz National University",
    descriptionAdvanced: {
      de: "Das alte Hauptgebäude der Kirgisischen Nationalen Universität in Bischkek ist ein herausragendes Denkmal der sowjetischen Architektur und ein Symbol für den akademischen Aufstieg des Landes. Gegründet im Jahr 1932, repräsentiert das Bauwerk den Übergang zur modernen Bildung in der Kirgisischen SSR. Mit seiner monumentalen Fassade, den klassischen Säulen und den weitläufigen Innenhöfen spiegelt es den Baustil des sozialistischen Klassizismus wider, der in der Mitte des 20. Jahrhunderts die Stadtplanung von Bischkek prägte. Das Gebäude war über Jahrzehnte das intellektuelle Zentrum des Landes, in dem die erste Generation kirgisischer Wissenschaftler und Politiker ausgebildet wurde. Auch heute noch beherbergt es wichtige Fakultäten und historische Hörsäle, die den Geist der Vergangenheit bewahren. Für Besucher und Studenten gleichermaßen ist der 'Alte Flügel' ein Ort der Beständigkeit, der die wechselvolle Geschichte Kirgisistans von der Sowjetära bis zur Unabhängigkeit erzählt und das architektonische Erbe der Hauptstadt bereichert.",
      hu: "A Kirgiz Nemzeti Egyetem biskeki főépülete a szovjet éra egyik legimpozánsabb építészeti emléke és az ország felsőoktatásának szimbóluma. Az intézményt 1932-ben alapították, és a régi épületszárny a kirgiz értelmiség bölcsőjeként vált ismertté. Az épület stílusa a szocialista klasszicizmus jegyeit hordozza; monumentális oszlopsoraival, díszes homlokzatával és tágas belső tereivel Biskek városképének meghatározó eleme. Az évtizedek során ez a falak között formálódott az ország tudományos és politikai elitje, így az épület nemcsak oktatási helyszín, hanem fontos történelmi emlékhely is. A belső terekben található történelmi előadótermek és könyvtárak ma is a tudományos élet aktív részei, megőrizve az alapítás korabeli hangulatot. Az egyetem régi szárnya a kirgiz főváros szívében található, emlékeztetve a látogatókat a modern Kirgizisztán oktatási fejlődésének gyökereire és a szovjet időszak grandiózus építészeti törekvéseire.",
      ro: "Aripa veche a Universității Naționale Kârgâze din Bișkek este un monument de referință al arhitecturii sovietice și un simbol central al istoriei educației din Kârgâzstan. Fondată în anul 1932, această clădire principală a servit ca fundație pentru dezvoltarea intelectuală a națiunii, fiind locul unde s-au format primele generații de savanți și lideri kârgâzi. Stilul arhitectural se încadrează în clasicismul socialist, caracterizat prin fațade monumentale cu coloane impunătoare și spații interioare vaste care reflectă importanța acordată științei în perioada sovietică. De-a lungul deceniilor, edificiul a rămas un nucleu al vieții academice, găzduind săli de curs istorice și laboratoare unde tradiția cercetării continuă și astăzi. Situată în inima capitalei, clădirea nu este doar o facilitate educațională, ci și un reper istoric care povestește despre transformările sociale și politice ale țării. Pentru locuitorii din Bișkek, universitatea reprezintă un punct de mândrie națională și un martor arhitectural al evoluției statului de la era sovietică până la independență.",
      en: "The historic main building of the Kyrgyz National University in Bishkek is an architectural masterpiece of the Soviet era and a cornerstone of the nation's higher education system. Founded in 1932, the 'Old Wing' represents the modernization of learning in Kyrgyzstan, housing the first significant academic faculties of the Kyrgyz SSR. The building's design follows the grand tradition of socialist classicism, featuring a monumental facade with stately columns and expansive courtyards that dominate its central location in the city. For nearly a century, these halls have nurtured the country's scientific, literary, and political elites, making the site a profound historical landmark. Inside, the original lecture halls and administrative chambers maintain their vintage aesthetic, preserving the intellectual atmosphere of the early 20th century. As Kyrgyzstan's premier academic institution, the old building remains a vibrant center of university life, standing as a testament to the enduring value of education and the rich Soviet-era architectural heritage that defines much of Bishkek's urban identity.",
      es: "El ala antigua de la Universidad Nacional de Kirguistán en Biskek es un edificio histórico de la década de 1930. Formó parte de la primera institución de educación superior del país, fundada en 1932. El edificio, de estilo constructivista, albergaba las facultades de humanidades y ciencias. Es un testimonio de la política educativa soviética en Asia Central. Tras varias renovaciones, hoy se sigue utilizando para seminarios y fines administrativos, destacando por su fachada blanca y grandes ventanales.",
      pt: "A ala antiga da Universidade Nacional do Quirguistão em Bishkek é um edifício histórico da década de 1930. Fez parte da primeira instituição de ensino superior do país, fundada em 1932. O edifício, em estilo construtivista, albergava as faculdades de humanidades e ciências naturais. É um testemunho da política educativa soviética na Ásia Central. Após várias renovações, é ainda hoje utilizado para seminários e fins administrativos, caracterizando-se pela sua fachada branca e janelas amplas.",
      fr: "L'ancienne aile de l'Université nationale kirghize à Bichkek est un bâtiment historique des années 1930. Elle faisait partie du premier établissement d'enseignement supérieur du pays, fondé en 1932. Le bâtiment de style constructiviste abritait les facultés des sciences humaines et des sciences naturelles. C'est un témoignage de la politique éducative soviétique en Asie centrale. Après plusieurs rénovations, il est aujourd'hui encore utilisé pour des séminaires et l'administration. L'aile se distingue par sa façade blanche et ses grandes fenêtres.",
    },
