    imageHint: "museum of Jalal-Abad history",
    descriptionAdvanced: {
      de: "Das Regionalmuseum von Dschalal-Abad wurde im Jahr 1927 gegründet und gehört zu den ältesten Kultureinrichtungen im Süden Kirgisistans. Die Sammlung umfasst mehr als 10.000 Exponate, die einen weiten Bogen von der Archäologie bis zur modernen Zeitgeschichte spannen. Ein besonderer Schwerpunkt des Museums liegt auf der Darstellung der einzigartigen Naturgeschichte der Region, insbesondere der weltberühmten Walnusswälder von Arslanbob. Besucher können hier antike Werkzeuge zur Holzbearbeitung und historische Dokumente zur frühen Forstwirtschaft bewundern. Die archäologische Abteilung präsentiert beeindruckende Funde aus dem Fergana-Tal, darunter handgefertigte Tonwaren aus dem 4. Jahrhundert und mittelalterliche Artefakte, die die Bedeutung der Region als Handelszentrum an der Seidenstraße belegen. Zudem bietet das Museum tiefe Einblicke in die kirgisische Ethnografie mit traditionellen Trachten, kunstvollen Teppichen und Alltagsgegenständen der Nomadenkultur, was es zu einem unverzichtbaren Ort für das Verständnis der regionalen Identität macht.",
      hu: "A Dzsalalabad-vidéki Múzeumot 1927-ben alapították, így ez az egyik legrégebbi kulturális intézmény Kirgizisztán déli részén. A gyűjtemény több mint 10 000 kiállítási tárgyat őriz, amelyek a régió gazdag történelmét és természeti örökségét mutatják be az őskortól napjainkig. A múzeum egyik legfontosabb szekciója a közeli Arslanbob híres dióerdőinek történetét dolgozza fel, bemutatva az ősi erdőgazdálkodási módszereket és a faipar jelentőségét. Az régészeti részlegben a Ferganai-medencéből származó leletek láthatók, többek között 4. századi agyagedények és középkori fegyverek, amelyek a Selyemút mentén zajló élénk kereskedelmi életre utalnak. Az etnográfiai kiállítás pedig a kirgiz nomád kultúra mindennapjaiba enged betekintést: díszes viseletek, kézzel szőtt szőnyegek és nemezből készült használati tárgyak sorakoznak a tárlókban. A múzeum nemcsak a múlt emlékeit őrzi, hanem fontos oktatási központ is, amely segít megérteni Közép-Ázsia ezen stratégiai fontosságú régiójának fejlődését.",
      ro: "Muzeul Regional din Jalal-Abad, înființat în 1927, este una dintre cele mai vechi și respectate instituții culturale din sudul Kârgâzstanului. Cu un patrimoniu ce depășește 10.000 de piese, muzeul oferă o imagine cuprinzătoare asupra evoluției regiunii din antichitate până în prezent. O secțiune specială este dedicată istoriei naturale, punând accent pe faimoasele păduri de nuc de la Arslanbob, unice în lume; aici sunt expuse unelte vechi de silvicultură și mostre de lemn prețios. Departamentul de arheologie găzduiește artefacte fascinante descoperite în Valea Fergana, inclusiv ceramică din secolul al IV-lea și obiecte medievale care atestă rolul crucial al orașului pe rutele comerciale ale Drumului Mătăsii. De asemenea, vizitatorii pot explora bogata tradiție etnografică a kârgâzilor, admirând costume populare brodate manual, covoare tradiționale „shyrdak” și obiecte de uz casnic folosite de nomazi. Muzeul reușește să păstreze vie memoria istorică a comunității, fiind un punct esențial de oprire pentru oricine dorește să înțeleagă rădăcinile culturale ale Asiei Centrale.",
      en: "The Jalal-Abad Regional Museum, established in 1927, is one of the oldest cultural landmarks in southern Kyrgyzstan. Its extensive collection features over 10,000 artifacts that detail the history, culture, and natural environment of the Jalal-Abad province. A significant portion of the museum is dedicated to the region's world-famous walnut forests, showcasing the history of forestry and the biodiversity of the nearby Arslanbob area. The archaeological department holds impressive finds from the Fergana Valley, including ancient pottery dating back to the 4th century and medieval coins that highlight the region's strategic importance on the Great Silk Road. Visitors can also explore an ethnographic exhibit that brings the Kyrgyz nomadic lifestyle to life through traditional costumes, intricately woven carpets, and household tools. As a center for historical preservation, the museum provides a vital link between the ancient traditions of the Fergana region and the modern Kyrgyz state, making it a must-visit for history enthusiasts and travelers alike.",
      es: "El Museo Regional de Jalal-Abad, en la ciudad homónima de Kirguistán, muestra la historia del óblast de Jalal-Abad. Fundado en 1976, alberga una colección de hallazgos arqueológicos del valle de Ferganá, incluyendo monedas, alfarería y vidrio de la época karajánida. El museo también documenta el desarrollo soviético de la región. Hay exposiciones sobre la industria local, especialmente la producción textil. El museo está alojado en un edificio histórico de principios del siglo XX. Es un centro para eventos culturales.",
      pt: "O Museu Regional de Jalal-Abad, na cidade com o mesmo nome no Quirguistão, exibe a história do Oblast de Jalal-Abad. Fundado em 1976, abriga uma coleção de achados arqueológicos do Vale de Fergana, incluindo moedas, cerâmica e vidro da época Caracanida. O museu também documenta o desenvolvimento soviético da região. Existem exposições sobre a indústria local, especialmente a produção têxtil. O museu está instalado num edifício histórico do início do século XX. É um centro para eventos culturais.",
      fr: "Le musée régional de Djalal-Abad, dans la ville du même nom au Kirghizistan, présente l'histoire de l'oblast de Djalal-Abad. Fondé en 1976, il abrite une collection de découvertes archéologiques de la vallée de Ferghana, notamment des pièces de monnaie, des poteries et du verre de l'époque karakhanide. Le musée documente également le développement soviétique de la région. Des expositions sont consacrées à l'industrie locale, en particulier la production textile. Le musée est installé dans un bâtiment historique du début du XXe siècle. C'est un centre d'événements culturels.",
    },
