    facts: {
      de: ["Ehemaliges Wohnhaus", "Persönliches Archiv", "Sowjetische Politikhistorie", "Kirgisische Unabhängigkeit"],
      hu: ["Egykori lakóház", "Személyes archívum", "Szovjet politikatörténet", "Kirgiz függetlenségi törekvések"],
      ro: ["Fostă locuință", "Arhivă personală", "Istorie politică sovietică", "Eforturi pentru independență"],
      en: ["Former private residence", "Contains personal archives", "Soviet era political history", "Kyrgyz statehood records"],
      es: ["Antigua casa residencial", "Archivo personal", "Historia política soviética", "Independencia de Kirguistán"],
      pt: ["Antiga casa residencial", "Arquivo pessoal", "História política soviética", "Independência do Quirguistão"],
      fr: ["Ancienne maison d'habitation", "Archives personnelles", "Histoire politique soviétique", "Indépendance du Kirghizistan"],
    },
    imageHint: "house museum of Iskhak Razzakov",
    descriptionAdvanced: {
      de: "Das Iskhak-Razzakow-Museum in Bischkek ist ein bedeutender Ort des kirgisischen Nationalstolzes und der politischen Geschichte. Es befindet sich in dem ehemaligen Wohnhaus, in dem Iskhak Razzakow, der erste Sekretär der Kommunistischen Partei Kirgisiens, während seiner Amtszeit lebte. Razzakow gilt als eine der herausragendsten Persönlichkeiten des 20. Jahrhunderts in Kirgisistan, da er in den 1950er Jahren die Modernisierung der Industrie, des Bildungswesens und der Kultur maßgeblich vorantrieb. Das Museum bewahrt sein persönliches Archiv, seltene Fotografien und Möbelstücke aus der Sowjetära auf, die einen authentischen Einblick in seinen bescheidenen Lebensstil und seine Vision für ein eigenständiges Kirgisistan bieten. Die Ausstellungen beleuchten nicht nur seinen politischen Aufstieg, sondern auch seinen moralischen Kompass und seine Bemühungen, die nationale Identität innerhalb des sowjetischen Systems zu stärken. Ein Besuch des Museums vermittelt tiefe Einblicke in die Ära des Aufbaus und der Transformation der kirgisischen Gesellschaft.",
      hu: "A biskeki Iszhak Razzakov Emlékmúzeum Kirgizisztán újkori történelmének és politikai fejlődésének egyik legfontosabb emlékhelye. A múzeum abban az egykori lakóházban kapott helyet, ahol Iszhak Razzakov, a Kirgiz Kommunista Párt első titkára élt és dolgozott 1950 és 1961 között. Razzakovot nemzeti hősként tisztelik, mivel elévülhetetlen érdemeket szerzett az ország modernizálásában, az ipar fejlesztésében és a kirgiz nemzeti kultúra támogatásában a szovjet éra alatt. A kiállítás bemutatja személyes archívumát, levelezéseit, fényképeit és eredeti bútoraival berendezett szobáit, amelyek hűen tükrözik szerény életmódját és elkötelezettségét. A múzeum nemcsak egy politikus életútját vázolja fel, hanem bemutatja azt a korszakot is, amikor Kirgizisztán alapvető gazdasági és társadalmi átalakuláson ment keresztül. Razzakov integritása és népe iránti szeretete ma is példaképként szolgál a kirgiz fiatalok számára, a múzeum pedig fontos központja a nemzeti emlékezetnek.",
      ro: "Muzeul Iskhak Razzakov din Bișkek este un loc de o profundă semnificație istorică, dedicat unuia dintre cei mai respectați lideri ai Kârgâzstanului din perioada sovietică. Muzeul este amenajat în fosta reședință privată unde Razzakov a locuit în timpul mandatului său ca prim-secretar al Partidului Comunist din Kirghizia (1950-1961). Iskhak Razzakov este considerat un arhitect al Kârgâzstanului modern, fiind cel care a pus bazele industrializării, educației superioare și instituțiilor culturale naționale. Expoziția cuprinde obiecte personale, documente de arhivă, fotografii rare și mobilier original, oferind o imagine clară asupra vieții sale modeste și a integrității sale profesionale. Muzeul nu doar onorează memoria unui om de stat, ci documentează și o epocă de transformări majore pentru poporul kârgâz. Pentru vizitatori, acest muzeu memorial reprezintă o fereastră către istoria politică a regiunii și o dovadă a eforturilor de afirmare a identității naționale kârgâze într-un context geopolitic complex.",
      en: "The Iskhak Razzakov Museum in Bishkek is a significant cultural site dedicated to the life and legacy of one of Kyrgyzstan's most esteemed political figures. Located in the modest former home of Iskhak Razzakov, who served as the First Secretary of the Communist Party of Kirghizia from 1950 to 1961, the museum offers a personal look at a leader often called the father of modern Kyrgyzstan. Razzakov was instrumental in driving the country's post-war industrialization, expanding its educational system, and fostering a sense of national pride. The museum's collection includes his personal library, private archives, photographs, and original furniture, reflecting his disciplined and humble character. Exhibits detail his strategic decisions that shaped the republic's economy and his efforts to promote Kyrgyz culture within the Soviet framework. Visiting the museum provides valuable context for understanding the socio-political evolution of Kyrgyzstan and the enduring impact of Razzakov's leadership on the nation's path to eventual statehood.",
      es: "El Museo Iskhak Razzakov en Biskek está dedicado al primer secretario del Partido Comunista de Kirguistán, que ejerció de 1950 a 1961. Razzakov fue fundamental en la industrialización y urbanización de la república soviética. El museo se inauguró en 2014 y muestra objetos personales, fotografías y documentos. Se encuentra en la casa donde vivió. Las exhibiciones destacan el desarrollo político y económico de Kirguistán bajo su mando. El museo es un lugar de recuerdo del pasado soviético.",
      pt: "O Museu Iskhak Razzakov em Bishkek é dedicado ao primeiro secretário do Partido Comunista do Quirguistão, que serviu de 1950 a 1961. Razzakov foi fundamental na industrialização e urbanização da república soviética. O museu abriu em 2014 e exibe objetos pessoais, fotografias e documentos. Está localizado na casa onde ele viveu. As exposições destacam o desenvolvimento político e económico do Quirguistão sob a sua liderança. O museu é um local de memória do passado soviético.",
      fr: "Le musée Iskhak Razzakov à Bichkek est dédié au premier secrétaire du Parti communiste du Kirghizistan, en fonction de 1950 à 1961. Razzakov a joué un rôle déterminant dans l'industrialisation et l'urbanisation de la république soviétique. Le musée a été inauguré en 2014 et présente des objets personnels, des photographies et des documents. Il est situé dans la maison où il a vécu. Les expositions mettent en lumière le développement politique et économique du Kirghizistan sous sa direction. Le musée est un lieu de mémoire du passé soviétique.",
    },
